INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118389, 'ruRU', '', 'Истязание наносит урон со временем, так что не нужно использовать его снова, пока эффект действует на цель.', 24330),
(118390, 'ruRU', '', 'Твоя способность Терзание также наносит дополнительный урон кровоточащим целям, так что эти способности отлично сочетаются.', 24330),
(118391, 'ruRU', '', 'Истязание заставит твою цель кровоточить, раня её с течением времени.', 24330),
(118392, 'ruRU', '', 'Как только ты подобрался к своей жертве в скрытности, время устроить засаду.', 24330),
(118393, 'ruRU', '', 'Когда у тебя будет 5 очков комбо, используй Свирепый укус на тренировочном манекене.', 24330),
(118394, 'ruRU', '', 'Старайся использовать его, когда у тебя полные 5 очков комбо.', 24330),
(118395, 'ruRU', '', 'Свирепый укус — завершающий приём, наносящий больше урона, чем больше у тебя очков комбо.', 24330),
(118396, 'ruRU', '', 'Обе твои способности, Терзание и Истязание, накапливают очки комбо, которые питают мощные завершающие приёмы.', 24330),
(118397, 'ruRU', '', 'Используй Терзание на тренировочном манекене, пока он кровоточит от Истязания.', 24330),
(118398, 'ruRU', '', 'Хотя и мощное само по себе, использование Терзания на кровоточащей цели увеличивает его урон, так что старайся поддерживать Истязание активным.', 24330),
(118399, 'ruRU', '', 'Твоя основная атака — Терзание.', 24330),
(118400, 'ruRU', '', 'Скрытность длится, пока ты не отменишь её, не атакуешь или не получишь урон.', 24330),
(118401, 'ruRU', '', 'Используй Выслеживание, чтобы войти в скрытность.', 24330),
(118402, 'ruRU', '', 'В облике кота ты можешь двигаться с поразительной незаметностью, позволяя подбираться к врагам незамеченным. Выслеживание переводит тебя в режим скрытности.', 24330),
(118403, 'ruRU', '', 'Используй Облик кота и прими форму кота.', 24330),
(118404, 'ruRU', '', 'Скоро они будут достаточно слабы, чтобы ты мог вцепиться им в горло мощным завершающим приёмом.', 24330),
(118405, 'ruRU', '', 'Будучи друидом-дикарём, твоё главное оружие — смена облика. В Облике кота твои когти и клыки раздирают противников, заставляя их кровоточить.', 24330),
(118406, 'ruRU', '', 'Ты не в Облике кота!', 24330),
(118407, 'ruRU', '', 'Тебе нужно быть в Облике кота, чтобы сражаться!', 24330),
(118408, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как друид-дикарь.', 24330),
(118409, 'ruRU', '', 'Покажи мне, что ты сражаешься с дикостью и хитростью!', 24330),
(118410, 'ruRU', '', 'Вспышка ярости продолжает наносить урон твоим врагам на короткое время, так что не нужно использовать её снова, пока эффект действует на цели.', 24330),
(118411, 'ruRU', '', 'Используй Вспышку ярости, чтобы нанести урон нескольким врагам одновременно.', 24330),
(118412, 'ruRU', '', 'Вспышка ярости наносит урон всем находящимся рядом врагам, заставляя их кровоточить на короткое время.', 24330),
(118413, 'ruRU', '', 'Сражаясь с несколькими врагами одновременно, друид-дикарь может стать вихрем клыков и когтей, нанося урон всему вокруг себя.', 24330),
(118414, 'ruRU', '', 'Используй Коготь, чтобы нанести урон нескольким врагам одновременно.', 24330),
(118415, 'ruRU', '', 'Коготь наносит урон всем находящимся рядом врагам, но этот урон увеличивается, если цели кровоточат. Хорошая идея — использовать Вспышку ярости и Коготь вместе.', 24330),
(118416, 'ruRU', '', 'Вспышка ярости — не единственный твой инструмент для борьбы с несколькими врагами.', 24330),
(118417, 'ruRU', '', 'Используй Инстинкт выживания, чтобы снизить получаемый урон.', 24330),
(118418, 'ruRU', '', 'Инстинкт выживания снижает получаемый урон на короткое время. Сохрани его на момент, когда он действительно понадобится!', 24330),
(118419, 'ruRU', '', 'В Облике кота ты можешь рассчитывать на инстинкты животного, чтобы выдержать тяжёлый бой.', 24330),
(118420, 'ruRU', '', 'Используй Опутывающие корни, чтобы приковать моего солдата к земле.', 24330),
(118421, 'ruRU', '', 'Опутывающие корни заставят растительные корни вырваться из земли и удержать цель на месте на короткое время.', 24330),
(118422, 'ruRU', '', 'Иногда тебе нужно, чтобы враг оставался на месте, чтобы ты мог сократить расстояние до него... или совершить поспешное отступление.', 24330),
(118423, 'ruRU', '', 'Используй Раздирание на тренировочном манекене с пятью очками комбо.', 24330),
(118424, 'ruRU', '', 'Как и Свирепый укус, Раздирание — завершающий приём, который лучше всего использовать, когда у тебя 5 очков комбо.', 24330),
(118425, 'ruRU', '', 'В качестве альтернативы Свирепому укусу, Раздирание можно использовать, чтобы наносить кровоточащий урон цели с течением времени, и это хорошая способность, на которую стоит тратить очки комбо в начале боя.', 24330),
(118426, 'ruRU', '', 'Используй Облик кота.', 24330),
(118427, 'ruRU', '', 'Использование заклинаний обычно выводит тебя из облика. Не забывай возвращаться в облик кота для боя.', 24330),
(118428, 'ruRU', '', 'Используй Повторный рост, чтобы полностью восстановить своё здоровье.', 24330);
